// Alexa's TTS chokes on markup and reads punctuation soup badly.
// server_brain.py already emits clean prose, but this flow may also be
// fed from elsewhere, so normalise defensively.
let text = String(msg.payload || '').trim();

// Strip anything that would be read out literally or break SSML.
text = text.replace(/[*_`~<>]/g, '');
text = text.replace(/\s+/g, ' ').trim();

if (!text) {
    text = 'Sorry, I have nothing to report.';
}

// Keep it short: Alexa talks over itself past roughly 12 seconds.
if (text.length > 300) {
    text = text.slice(0, 297) + '...';
}

msg.payload = text;
return msg;
